-- Comunidad de ejemplo de Pico Criollo: 24 criaderos con granjas, fotos, 312 publicaciones del muro, 370 avisos del mercado,
-- 250 seguimientos, 2288 me gusta y 684 comentarios. Generado el 2026-10-20T19:01:53.812Z por scripts/export-seed-sql.ts.
-- Todo es inventado. Las cuentas usan correos @semilla.pico-criollo.invalid y no pueden iniciar sesión.
-- Se puede ejecutar varias veces (ON CONFLICT DO NOTHING). Para quitarlo todo: borrar-comunidad-ejemplo.sql.
-- Ejecútalo conectado a la base de la app (por ejemplo bdpicocriollo) en pgAdmin > Query Tool.

BEGIN;

-- Tablas (solo se crean si faltan)
-- Generado por scripts/gen-migration.ts desde src/server/storage/specs.ts. No editar a mano.
-- Cada colección nueva es una tabla (id, data jsonb) con índices y únicos sobre campos clave.

CREATE TABLE IF NOT EXISTS app_users (
  id uuid PRIMARY KEY,
  email text NOT NULL UNIQUE,
  password_hash text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE app_users ADD COLUMN IF NOT EXISTS profile jsonb NOT NULL DEFAULT '{}'::jsonb;

CREATE TABLE IF NOT EXISTS app_sessions (
  token_hash char(64) PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
  expires_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS app_sessions_user_id_idx ON app_sessions(user_id);
CREATE INDEX IF NOT EXISTS app_sessions_expiry_idx ON app_sessions(expires_at);

CREATE TABLE IF NOT EXISTS farm_data (
  user_id uuid PRIMARY KEY REFERENCES app_users(id) ON DELETE CASCADE,
  data jsonb NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS pc_media (
  id text PRIMARY KEY,
  mime text NOT NULL,
  owner_id text NOT NULL,
  bytes bytea NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

