  ('83fdb51b-ff49-4c1e-a284-64e92fa52571', $seed${"id":"83fdb51b-ff49-4c1e-a284-64e92fa52571","authorId":"c2048b3a-332a-4d4c-a6de-55e939717fc8","text":"17 pollitos de Criolla ya con plumas y listos para pasar a la pollera grande. Gracias a Luna, la mejor mamá. #Pollitos #Criolla","mediaIds":["81c731d3-7d66-449e-a67c-c2b2edc95bc2"],"createdAt":"2026-09-28T20:01:53.812Z","updatedAt":"2026-09-28T20:01:53.812Z"}$seed$::jsonb),
