INSERT INTO pc_posts (id, data) VALUES
  ('22b3c756-2926-4eb5-bd35-e8fac9c5fc97', $seed${"id":"22b3c756-2926-4eb5-bd35-e8fac9c5fc97","authorId":"f38007a8-1eec-40ee-9f3f-1e0e4827636c","text":"Así luce Panela, mi Cubana consentida del gallinero Huerta. Tiene un carácter... pero pone todos los días. #Cubana #Gallinas","mediaIds":["f013cd8b-13f6-469b-a52a-59ffae0d56ed"],"createdAt":"2026-10-08T02:01:53.812Z","updatedAt":"2026-10-08T02:01:53.812Z"}$seed$::jsonb),
