  ('a890be77-5c1e-4507-a28e-38c766be78ad', $seed${"id":"a890be77-5c1e-4507-a28e-38c766be78ad","authorId":"bf3f4e00-abb2-40b7-bb6f-8cc50618d7e0","text":"Camada nueva en el gallinero Cafetal: 11 pollitos Araucana con calor y agua con panela. #Pollitos #Criadero","mediaIds":["4935e7f5-0133-41ac-9b61-f8a82b511eae"],"createdAt":"2026-10-08T18:01:53.812Z","updatedAt":"2026-10-08T18:01:53.812Z"}$seed$::jsonb),
  ('dc361a1e-79de-4b62-9868-f6c952d90b7e', $seed${"id":"dc361a1e-79de-4b62-9868-f6c952d90b7e","authorId":"bf3f4e00-abb2-40b7-bb6f-8cc50618d7e0","text":"Nido lleno: 11 huevos de Araucana en un solo día. Así es la postura en La Ceja con este clima. #Huevos #Araucana","mediaIds":["6851eaee-0646-4c7a-9aa1-1638357652cf"],"createdAt":"2026-10-05T13:01:53.812Z","updatedAt":"2026-10-05T13:01:53.812Z"}$seed$::jsonb),
