INSERT INTO pc_posts (id, data) VALUES
  ('3a0010f9-8c5c-4618-bdd7-0604f8c3a63d', $seed${"id":"3a0010f9-8c5c-4618-bdd7-0604f8c3a63d","authorId":"3e03d3ff-a973-478f-b996-581cbbcae111","text":"Por fin llegó la lluvia y los patios se pusieron verdes. Las gallinas felices escarbando. #Gallinas #Sussex","mediaIds":[],"createdAt":"2026-10-16T16:01:53.812Z","updatedAt":"2026-10-16T16:01:53.812Z"}$seed$::jsonb),
  ('2bd3240c-14b4-474c-b42d-0c7521bde4e5', $seed${"id":"2bd3240c-14b4-474c-b42d-0c7521bde4e5","authorId":"3e03d3ff-a973-478f-b996-581cbbcae111","text":"Salieron 20 pollitos Leghorn de la última incubación. Todos activos y comiendo bien. #Pollitos #Leghorn","mediaIds":["51907887-10db-45e4-a534-dbacddfb4cd5"],"createdAt":"2026-10-13T23:01:53.812Z","updatedAt":"2026-10-13T23:01:53.812Z"}$seed$::jsonb),
