  ('f21dbb70-1ad5-433d-871d-91406865a296', $seed${"id":"f21dbb70-1ad5-433d-871d-91406865a296","authorId":"3e03d3ff-a973-478f-b996-581cbbcae111","text":"31 pollitos de Criolla ya con plumas y listos para pasar a la pollera grande. Gracias a Alondra, la mejor mamá. #Pollitos #Criolla","mediaIds":["9854326e-e827-4e80-8c3d-8cda59b06221"],"createdAt":"2026-10-11T02:01:53.812Z","updatedAt":"2026-10-11T02:01:53.812Z"}$seed$::jsonb),
  ('1c6cb2a6-cd3f-4803-a15e-81b8440b660a', $seed${"id":"1c6cb2a6-cd3f-4803-a15e-81b8440b660a","authorId":"3e03d3ff-a973-478f-b996-581cbbcae111","text":"General estrenando cresta y plumaje de la temporada. Un Leghorn de buen porte, hijo de mis mejores reproductores. #Leghorn #Gallos","mediaIds":["8bda5a3a-43ce-473f-8675-1fe82bb753d0"],"createdAt":"2026-10-08T13:01:53.812Z","updatedAt":"2026-10-08T13:01:53.812Z"}$seed$::jsonb),
