  ('006c228a-0608-4e9f-954e-b3bf8ceb20a5', $seed${"id":"006c228a-0608-4e9f-954e-b3bf8ceb20a5","authorId":"3e03d3ff-a973-478f-b996-581cbbcae111","text":"Mañana de sol en Tunja y Margarita (raza Leghorn) tomando su baño de arena. Así da gusto criar. #Leghorn #Criadero","mediaIds":["a7241c69-db62-4c0a-b3b9-a48cba2dff6e"],"createdAt":"2026-10-04T22:01:53.812Z","updatedAt":"2026-10-04T22:01:53.812Z"}$seed$::jsonb),
  ('02eaf177-2211-4096-8894-3644b4e48d58', $seed${"id":"02eaf177-2211-4096-8894-3644b4e48d58","authorId":"3e03d3ff-a973-478f-b996-581cbbcae111","text":"Mañana de sol en Tunja y Rosita (raza Leghorn) tomando su baño de arena. Así da gusto criar. #Leghorn #Criadero","mediaIds":[],"createdAt":"2026-10-02T02:01:53.812Z","updatedAt":"2026-10-02T02:01:53.812Z"}$seed$::jsonb),
